create table tanks (active bit not null, capacity_amount float(53) not null, configuration_version integer not null, level_amount float(53) not null, created_at datetime(6) not null, customer_account_id bigint not null, id bigint not null auto_increment, legacy_equipment_id bigint, organization_id bigint not null, site_id bigint, updated_at datetime(6) not null, level_observed_at datetime(6), capacity_unit varchar(20) not null, level_unit varchar(20) not null, level_source varchar(20), fuel_type varchar(30), name varchar(150) not null, classification VARCHAR(20) not null, primary key (id)) engine=InnoDB;
alter table tanks add constraint uk_tanks_legacy_equipment unique (legacy_equipment_id);
create table tank_configurations (capacity_amount float(53) not null, version integer not null, created_at datetime(6) not null, id bigint not null auto_increment, recorded_at datetime(6) not null, tank_id bigint not null, updated_at datetime(6) not null, capacity_unit varchar(20) not null, fuel_type varchar(30), primary key (id)) engine=InnoDB;
